const cliDeadlineMs = 45_000;
const seedAndVerificationMs = 30_000;

async function cli(env: NodeJS.ProcessEnv, args: string[], input: string, sensitive: string[]) {
  const child = spawn(
    process.execPath,
    ["--import", "tsx", "apps/control-api/src/access-cli.ts", ...args],
    {
      env,
      windowsHide: true,
      stdio: ["pipe", "pipe", "pipe"],
    },
  );
  let output = "";
  child.stdout.on("data", (chunk: Buffer) => {
    output += chunk.toString();
  });
  child.stderr.on("data", (chunk: Buffer) => {
    output += chunk.toString();
  });
  child.stdin.end(input);
  let timedOut = false;
  const timer = setTimeout(() => {
    timedOut = true;
    child.kill("SIGKILL");
  }, cliDeadlineMs);
  try {
    const [code] = await once(child, "close");
    return {
      code,
      timedOut,
      leaked: sensitive.some((value) => Boolean(value) && output.includes(value)),
    };
  } finally {
    clearTimeout(timer);
  }
}

async function cleanup(directory: string) {
  const nested = relative(resolve(tmpdir()), resolve(directory));
  if (!nested.startsWith("godseye-access-cli-") || isAbsolute(nested))
    throw new Error("Refusing cleanup outside the owned CLI fixture");
  await rm(directory, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 });
}

describe("private stdin/file access administration against real OpenBao", () => {
  let lab: OpenBaoFixture;
  let controllerProof = "";
  beforeAll(async () => {
    lab = await openBaoFixture();
    await lab.unseal();
    await lab.admin("/sys/mounts/godseye", {
      method: "POST",
      body: { type: "kv", options: { version: "2" } },
    });
    await lab.admin(`/sys/policies/acl/${BAO_BROKER_POLICY}`, {
      method: "PUT",
      body: { policy: compileBrokerPolicy() },
    });
    const issued = await lab.admin("/auth/token/create", {
      method: "POST",
      body: { policies: [BAO_BROKER_POLICY], no_default_policy: true, renewable: false, ttl: "1h" },
    });
    const auth = issued.body.auth;
    if (
      !auth ||
      typeof auth !== "object" ||
      !("client_token" in auth) ||
      typeof auth.client_token !== "string"
    )
      throw new Error("Scoped CLI fixture provider authority missing");
    controllerProof = auth.client_token;
  }, 90_000);
  afterAll(async () => {
    controllerProof = "";
    await lab?.close();
  }, 30_000);

  it("T08 renews limited provider authority only with explicit private replacement", {
    timeout: 3 * cliDeadlineMs + seedAndVerificationMs,
  }, async () => {
    const directory = await mkdtemp(join(tmpdir(), "godseye-access-cli-"));
    const stateDir = join(directory, "state");
    const issued = await lab.admin("/auth/token/create", {
      method: "POST",
      body: { policies: [BAO_BROKER_POLICY], no_default_policy: true, renewable: false, ttl: "1h" },
    });
    const auth = issued.body.auth;
    if (
      !auth ||
      typeof auth !== "object" ||
      !("client_token" in auth) ||
      typeof auth.client_token !== "string"
    )
      throw new Error("Replacement fixture provider authority missing");
    const replacement = auth.client_token;
    const env = {
      ...process.env,
      GODSEYE_MODE: "local",
      NODE_ENV: "development",
      GODSEYE_DATABASE_URL: "",
      GODSEYE_DATA_DIR: join(directory, "control"),
      GODSEYE_STATE_DIR: stateDir,
      GODSEYE_BAO_ADDRESS: lab.url,
      GODSEYE_BAO_MOUNT: "godseye",
    };
    const sensitive = [controllerProof, replacement];
    try {
      expect(await cli(env, ["provider-auth"], controllerProof, sensitive)).toEqual({
        code: 0,
        timedOut: false,
        leaked: false,
      });
      expect(await cli(env, ["provider-auth"], replacement, sensitive)).toEqual({
        code: 1,
        timedOut: false,
        leaked: false,
      });
      const path = join(stateDir, "owner", "bao.auth");
      expect((await readFile(path, "utf8")) === controllerProof).toBe(true);
      expect(await cli(env, ["provider-auth", "--replace"], replacement, sensitive)).toEqual({
        code: 0,
        timedOut: false,
        leaked: false,
      });
      expect((await readFile(path, "utf8")) === replacement).toBe(true);
    } finally {
      await cleanup(directory);
    }
  });

  it("T-AC-14 T08 imports through stdin and issues a replayable private proof without printing values", {
    // Five child deadlines plus seed/reopen/verification must precede scenario cancellation.
    timeout: 5 * cliDeadlineMs + seedAndVerificationMs,
  }, async () => {
    const directory = await mkdtemp(join(tmpdir(), "godseye-access-cli-"));
    const stateDir = join(directory, "state");
    const dataDir = join(directory, "control");
    await privateDirectory(stateDir);
    const signingKey = await loadIdentityMaterial(join(stateDir, "owner"));
    const provider = new BaoAccessProvider({ address: lab.url, proof: () => controllerProof });
    let store: Awaited<ReturnType<typeof openStore>> | undefined;
    try {
      store = await openStore({ dataDir });
      const ownerIdentity = await createOwnerIdentity(store, {
        origin: "http://localhost:4300",
        signingKey,
      });
      const owner = {
        id: ownerIdentity.ownerId,
        kind: "owner" as const,
        projectIds: [],
        sessionId: "private-fixture",
        authenticatedAt: new Date().toISOString(),
      };
      const project = await new ControlPlane(store).createProject(
        owner,
        { ...projectInput, slug: "private-cli-fixture" },
        randomUUID(),
      );
      const environment = project.environments[0];
      if (!environment) throw new Error("CLI fixture environment missing");
      const broker = new AccessBroker(store, {
        foundation: new FoundationEngine(store),
        provider,
        fingerprintKey: signingKey,
      });
      const identity = await broker.createIdentity(
        owner,
        {
          projectId: project.id,
          environmentId: environment.id,
          purpose: "runtime",
          name: "CLI service",
        },
        randomUUID(),
      );
      const slot = await broker.createSlot(
        owner,
        { identityId: identity.id, name: "Private fixture slot" },
        randomUUID(),
      );
      await store.close();
      store = undefined;
      const env = {
        ...process.env,
        GODSEYE_MODE: "local",
        NODE_ENV: "development",
        GODSEYE_DATABASE_URL: "",
        GODSEYE_DATA_DIR: dataDir,
        GODSEYE_STATE_DIR: stateDir,
        GODSEYE_BAO_ADDRESS: lab.url,
      };
      const value = randomUUID();
      expect(await cli(env, ["provider-auth"], controllerProof, [controllerProof, value])).toEqual({
        code: 0,
        timedOut: false,
        leaked: false,
      });
      const stageArgs = ["stage", "--slot", slot.id, "--revision", "1", "--key", randomUUID()];
      expect(await cli(env, stageArgs, value, [controllerProof, value])).toEqual({
        code: 0,
        timedOut: false,
        leaked: false,
      });
      expect(await cli(env, stageArgs, value, [controllerProof, value])).toEqual({
        code: 0,
        timedOut: false,
        leaked: false,
      });
      const issueArgs = [
        "issue",
        "--identity",
        identity.id,
        "--revision",
        "1",
        "--key",
        randomUUID(),
      ];
      expect(await cli(env, issueArgs, "", [controllerProof, value])).toEqual({
        code: 0,
        timedOut: false,
        leaked: false,
      });
      const proofPath = join(stateDir, "owner", "handoffs", `${identity.id}.2.proof`);
      const proof = await readFile(proofPath, "utf8");
      expect(await cli(env, issueArgs, "", [controllerProof, value, proof])).toEqual({
        code: 0,
        timedOut: false,
        leaked: false,
      });
      store = await openStore({ dataDir });
      const transition = transitionFixture();
      const restored = new AccessBroker(store, {
        foundation: new FoundationEngine(store),
        provider,
        fingerprintKey: signingKey,
        transitions: [transition.adapter],
      });
      const overview = await restored.overview(owner);
      const staged = overview.slots.find((row) => row.id === slot.id);
      expect(staged?.stagedVersion).toBe(1);
      expect(overview.operations.filter((row) => row.kind === "stage")).toHaveLength(1);
      if (!staged) throw new Error("CLI staged slot missing");
      // A fixture transition tests the private handoff; it does not qualify a real database target.
      await restored.activate(
        { ...owner, authenticatedAt: new Date().toISOString() },
        slot.id,
        transition.adapter.id,
        staged.revision,
        randomUUID(),
      );
      let delivered = false;
      await restored.consumeStatic(proof, slot.id, (material) => {
        delivered = material === value;
      });
      expect(delivered).toBe(true);
    } finally {
      await store?.close();
      await cleanup(directory);
    }
  });

  it("T08 T37 refuses provider import while another local process owns the state lock", {
    timeout: cliDeadlineMs + seedAndVerificationMs,
  }, async () => {
    const directory = await mkdtemp(join(tmpdir(), "godseye-access-cli-"));
    const stateDir = join(directory, "state");
    await privateDirectory(stateDir);
    const release = await acquireInstance(stateDir);
    try {
      const env = {
        ...process.env,
        GODSEYE_MODE: "local",
        NODE_ENV: "development",
        GODSEYE_DATABASE_URL: "",
        GODSEYE_DATA_DIR: join(directory, "control"),
        GODSEYE_STATE_DIR: stateDir,
        GODSEYE_BAO_ADDRESS: lab.url,
      };
      expect(await cli(env, ["provider-auth"], controllerProof, [controllerProof])).toEqual({
        code: 1,
        timedOut: false,
        leaked: false,
      });
      let created = false;
      try {
        await readFile(join(stateDir, "owner", "bao.auth"));
        created = true;
      } catch (error) {
        if (!(error && typeof error === "object" && "code" in error && error.code === "ENOENT"))
          throw error;
      }
      expect(created).toBe(false);
    } finally {
      await release();
      await cleanup(directory);
    }
  });
});
